const archiveSnapshot = `-- name: ArchiveSnapshot :many
SELECT n.id AS node_id, n.selected_output_id AS output_id, n.selected_asset_id AS asset_id,
    a.source_asset_id, a.source_revision_id, coalesce(a.size_bytes, 0)::bigint AS media_size, coalesce(g.status, '')::text AS generation_status
FROM canvas_nodes n LEFT JOIN canvas_node_generations g ON g.task_run_id = n.selected_output_id
  AND g.tenant_id = n.tenant_id
  AND g.workspace_id IS NOT DISTINCT FROM n.workspace_id
  AND g.project_id = n.project_id
  AND g.canvas_id = n.canvas_id
  AND g.node_id = n.id
LEFT JOIN assets a ON a.id = g.asset_id
  AND a.id = n.selected_asset_id
  AND a.tenant_id = g.tenant_id
  AND a.workspace_id IS NOT DISTINCT FROM n.workspace_id
  AND a.owner_type = $1
  AND a.owner_id = n.project_id
  AND a.media_type = $2
  AND a.deleted_at = 0
WHERE n.tenant_id = $3
  AND n.workspace_id IS NOT DISTINCT FROM $4::varchar
  AND n.project_id = $5
  AND n.canvas_id = $6
  AND n.type = $7
  AND n.deleted_at = 0
  AND n.selected_output_id IS NOT NULL
ORDER BY n.storyboard_rank, n.id
`

type ArchiveSnapshotParams struct {
	OwnerType   int16
	MediaType   int16
	TenantID    string
	WorkspaceID *string
	ProjectID   string
	CanvasID    string
	Type        int16
}

type ArchiveSnapshotRow struct {
	NodeID           string
	OutputID         *string
	AssetID          *string
	SourceAssetID    *string
	SourceRevisionID *string
	MediaSize        int64
	GenerationStatus string
}

func (q *Queries) ArchiveSnapshot(ctx context.Context, arg ArchiveSnapshotParams) ([]ArchiveSnapshotRow, error) {
	rows, err := q.db.Query(ctx, archiveSnapshot,
		arg.OwnerType,
		arg.MediaType,
		arg.TenantID,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.CanvasID,
		arg.Type,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ArchiveSnapshotRow{}
	for rows.Next() {
		var i ArchiveSnapshotRow
		if err := rows.Scan(
			&i.NodeID,
			&i.OutputID,
			&i.AssetID,
			&i.SourceAssetID,
			&i.SourceRevisionID,
			&i.MediaSize,
			&i.GenerationStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

